mapper.select:
SELECT
    (
        SELECT COUNT(*)
        FROM (
            SELECT le.user_id
            FROM login_events le
            WHERE le.user_id IS NOT NULL
              AND le.event_type = 'LOGIN_SUCCESS'
              AND le.created_at >= #{dayStart}
              AND le.created_at < #{dayEnd}
            UNION
            SELECT rl.user_id
            FROM review_logs rl
            WHERE rl.reviewed_at >= #{dayStart}
              AND rl.reviewed_at < #{dayEnd}
        ) active_users
    ) AS today_active_users,
    (
        SELECT COUNT(*)
        FROM login_events le
        WHERE le.event_type = 'LOGIN_SUCCESS'
          AND le.created_at >= #{dayStart}
          AND le.created_at < #{dayEnd}
    ) AS today_login_count,
    (
        SELECT COUNT(DISTINCT rl.user_id)
        FROM review_logs rl
        WHERE rl.reviewed_at >= #{dayStart}
          AND rl.reviewed_at < #{dayEnd}
    ) AS today_review_users,
    (
        SELECT COUNT(*)
        FROM review_logs rl
        WHERE rl.reviewed_at >= #{dayStart}
          AND rl.reviewed_at < #{dayEnd}
    ) AS today_review_count,
    (
        SELECT COUNT(*)
        FROM users u
        WHERE u.created_at >= #{dayStart}
          AND u.created_at < #{dayEnd}
    ) AS today_new_users,
    (
        SELECT COUNT(*)
        FROM messages m
        WHERE m.created_at >= #{dayStart}
          AND m.created_at < #{dayEnd}
    ) AS today_message_count,
    (SELECT COUNT(*) FROM users) AS total_users,
    (SELECT COUNT(*) FROM words) AS total_words
